// Generated by scripts/fetch_year_photos.py -- do not edit by hand.
//
// A photograph for the jobs that have one. Most are CC BY or CC BY-SA, so the author
// and the licence travel with the picture and are shown wherever it is: that is the
// whole of what those licences ask for, and it is also the honest thing to show.
//
// Jobs without a photograph are not an oversight -- see WITHOUT in the script. They
// keep their drawn icon, and every layout here copes with a missing picture.

export type YearPhoto = {
  /** Path under /public, already cropped to 3:2 so nothing reflows when it lands. */
  file: string;
  /** A square tile for the phone list, a fortieth of the weight. */
  thumb: string;
  author: string;
  licence: string;
  licenceUrl: string;
  /** The file's page on Wikimedia Commons. */
  source: string;
};

