/**
 * The plant of each forage, so the bloom, the move and the harvest of one forage
 * show the same picture and read as one thread through the year.
 */
export const FORAGE_PHOTOS: Record<string, YearPhoto> = {
  "rapeseed": YEAR_PHOTOS["migrate-rapeseed"],
  "acacia": YEAR_PHOTOS["migrate-acacia"],
  "chestnut": YEAR_PHOTOS["migrate-chestnut"],
  "linden": YEAR_PHOTOS["migrate-linden"],
  "fir": YEAR_PHOTOS["migrate-fir"],
  "lavender": YEAR_PHOTOS["migrate-lavender"],
  "sunflower": YEAR_PHOTOS["migrate-sunflower"],
  "heather": YEAR_PHOTOS["migrate-heather"],
};

/**
 * The photograph for one calendar entry, or undefined when it has none.
 *
 * An entry that names a forage shows that plant, whatever the job is. Everything
 * else shows the job itself.
 */
export function photoFor(entryKey: string, honey?: string | null): YearPhoto | undefined {
  if (honey && FORAGE_PHOTOS[honey]) return FORAGE_PHOTOS[honey];
  return YEAR_PHOTOS[entryKey];
}

